var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`프린터의 KlipperScreen 터치스크린 설정을 안전하게 편집한 다음, KlipperScreen을 재시작해 적용하세요. 저장 시 항상 먼저 백업됩니다.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`도움말`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen Studio 소개`}},close:{t:0,b:{t:2,i:[{t:3}],s:`닫기`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`읽는 법`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`아래 설정 텍스트를 편집하세요(그대로 두어도 됩니다).`}},{t:0,b:{t:2,i:[{t:3}],s:`저장 - 현재 파일이 먼저 백업되며, 프린터가 작업 중이면 저장이 거부됩니다.`}},{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen을 재시작해 실제 화면에 변경 사항을 적용하세요.`}},{t:0,b:{t:2,i:[{t:3}],s:`줄 끝은 UNIX(LF)를 사용하며, 저장 시 자동으로 적용됩니다.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`용어집`}},body:{t:0,b:{t:2,i:[{t:3}],s:`여기서 사용되는 KlipperScreen 용어의 간단한 정의입니다.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Config 탭이란?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`원본 KlipperScreen.conf입니다. 모든 설정을 직접 편집할 수 있으며, 저장 시 파일을 먼저 백업하고, 프린터가 작업 중이면 거부되며, 불러온 이후 화면에서 파일이 변경되었으면 경고합니다. 대부분은 대신 Settings / Menus / Themes 탭을 사용합니다.`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Settings 탭이란?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`가장 많이 쓰는 [main] 옵션을 폼 형태로 제공합니다 - 테마, 언어, 화면 절전, 글꼴 크기, 토글 등. 현재 설정에서 미리 채워지며, 변경한 옵션만 기록됩니다. 적용하려면 재시작하세요.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Menus 탭이란?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`터치스크린의 버튼 그리드를 디자인합니다. 각 트리(__main은 홈 그리드, __print는 인쇄 화면)에 버튼이 나열되며, 추가·이름 변경·순서 변경·중첩이 가능하고, 각 버튼이 하위 메뉴 열기, 내장 화면 열기, 또는 G-code 실행을 하도록 설정할 수 있습니다.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Themes 탭이란?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen 테마를 만듭니다: 팔레트 토큰별로 색상과 모서리 반경을 고르고, 실시간 미리보기를 확인한 뒤 화면에 만들어 적용하세요. 미리보기는 근사치입니다 - 실제 화면은 GTK로 렌더링됩니다.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk 탭이란?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind Flow 자체를 전체 화면 브라우저로 터치스크린에 띄웁니다 - 화면에 표시되는 내용을 완전히 제어합니다. KlipperScreen과 되돌릴 수 있는 전환이며(기본은 일시적, 재부팅하면 KlipperScreen 복원), 프린터 호스트에서 일회성 설치 프로그램이 필요합니다.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`프린터에 연결된 소형 디스플레이에서 실행되는 터치스크린 UI로, 이 웹 패널과는 별개입니다.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`테마`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen의 외관 - 색상, 아이콘, 모서리 반경입니다. 호스트의 styles/<name> 폴더에 저장되며, 외형 전용입니다(레이아웃은 바꿀 수 없습니다).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`메뉴 (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen이 보여주는 버튼 그리드입니다. __main은 홈 화면, __print는 인쇄 중 표시되는 화면, __splashscreen은 시작 화면입니다.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`패널`}},def:{t:0,b:{t:2,i:[{t:3}],s:`버튼이 열 수 있는 내장 KlipperScreen 화면입니다(이동, 온도, 압출, 베드 메시 등). 내부 내용은 KlipperScreen이 고정합니다.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`자동 생성 블록 (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen이 conf 하단의 #~# 표시 뒤에 자체적으로 기록하는 섹션입니다. FilaMind은 이 부분을 절대 편집하지 않고, 그 위의 설정만 다룹니다.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`키오스크`}},def:{t:0,b:{t:2,i:[{t:3}],s:`터치스크린에 KlipperScreen 대신 전체 화면 브라우저를 실행해 화면에 FilaMind Flow를 표시하는 것입니다. 완전히 되돌릴 수 있습니다.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen 확인 중…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`이 프린터에서 KlipperScreen이 감지되지 않았습니다(KlipperScreen.conf 없음, Moonraker에도 보고되지 않음). 이 도구를 사용하려면 KlipperScreen을 설치하세요.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen 감지됨`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`테마`}},language:{t:0,b:{t:2,i:[{t:3}],s:`언어`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker가 KlipperScreen을 자동으로 재시작할 수 없습니다 - 저장 후 수동으로 재시작하세요.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf 읽는 중…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`다시 불러오기`}},save:{t:0,b:{t:2,i:[{t:3}],s:`설정 저장`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`저장 중…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`저장됨(백업 완료)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`저장되지 않은 변경 사항`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`프린터가 작업 중이라 거부되었습니다 - 유휴 상태일 때 다시 시도하세요.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf가 불러온 이후 디스크에서 변경되었습니다(화면에서 편집된 것으로 보임). 그 변경을 덮어쓰지 않도록 저장 전에 다시 불러오세요.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`구성`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`설정`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`메뉴`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`테마`}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind 화면`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`설정 불러오는 중…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`가장 많이 쓰는 KlipperScreen 디스플레이 옵션을 폼으로 제공합니다. 여기서 변경한 옵션만 기록되며, 나머지는 현재 값을 유지합니다. 적용하려면 재시작하세요.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`여기서 변경한 설정만 KlipperScreen.conf에 기록됩니다.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`설정 저장`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`저장됨 - 적용하려면 KlipperScreen을 재시작하세요.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`설정 안 함(기본값)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`안 함(항상 켜짐)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`작게`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`보통`}},large:{t:0,b:{t:2,i:[{t:3}],s:`크게`}},max:{t:0,b:{t:2,i:[{t:3}],s:`최대`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`테마`}},language:{t:0,b:{t:2,i:[{t:3}],s:`언어`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`화면 절전 시간`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`글꼴 크기`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`24시간제`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`DPMS로 화면 끄기`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`마우스 커서 표시`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`긴급 정지 전 확인`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`히터 출력 % 표시`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`팝업 자동 닫기`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`화면 확인 중…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind Flow 자체를 전체 화면 브라우저로 터치스크린에 띄웁니다 - 화면에 표시되는 내용을 완전히 제어합니다. KlipperScreen과 전환되며, 하나를 시작하면 다른 하나가 멈춥니다.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`현재 화면`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind 키오스크`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`둘 다 실행 안 됨`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`키오스크가 아직 설치되지 않음`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`프린터 호스트에서 한 번 실행하세요(전체 화면 브라우저 + 키오스크 서비스 설치):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`부팅 시 기본값으로 설정합니다(그러지 않으면 전환은 일시적이며, 재부팅하면 다른 쪽이 복원됩니다).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`기본은 일시적입니다: 재부팅하면 다른 쪽이 돌아옵니다. 화면이 꺼지면 SSH로 다음을 실행하세요: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind로 전환`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen 복원`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`새로고침`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`화면에 FilaMind을 띄울까요?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen을 복원할까요?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`한 화면 서비스를 멈추고 다른 하나를 시작합니다. 진행 중인 인쇄에는 영향을 주지 않지만, 전환되는 동안 터치스크린이 몇 초간 검게 표시됩니다.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`실행`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`취소`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind이 화면을 넘겨받는 중입니다 - 몇 초 안에 나타납니다.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen이 돌아오는 중입니다 - 곧 화면이 복원됩니다.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`메뉴 불러오는 중…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`터치스크린에 표시할 내용을 디자인합니다: 각 메뉴의 버튼, 순서, 그리고 각 버튼의 동작. 홈 화면 그리드는 __main 트리이고, 인쇄 화면은 __print입니다.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`버튼 추가`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`아직 항목이 없습니다 - 하나 추가하세요.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`위로 이동`}},down:{t:0,b:{t:2,i:[{t:3}],s:`아래로 이동`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`하위 항목 추가`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`삭제`}},name:{t:0,b:{t:2,i:[{t:3}],s:`이름`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`아이콘`}},action:{t:0,b:{t:2,i:[{t:3}],s:`동작`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`하위 메뉴 열기`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`화면 열기`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code 실행`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`화면`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`표시 조건`}},save:{t:0,b:{t:2,i:[{t:3}],s:`메뉴 저장`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`새 버튼`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`메뉴가 저장되었습니다 - 보려면 KlipperScreen을 재시작하세요.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`테마 불러오는 중…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`팔레트`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`모서리 반경`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`실시간 미리보기`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`버튼`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`경고`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`근사 미리보기 - 실제 화면은 GTK로 렌더링되며, 약간의 차이는 정상입니다.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`새 테마 이름`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`만들고 적용`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`만들기만`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`설치된 테마`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`적용`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`테마 삭제`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`여기서 만듦`}},created:{t:0,b:{t:2,i:[{t:3}],s:`테마가 생성되었습니다. 목록에서 적용한 뒤 재시작하세요.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`테마 설정됨 - 보려면 KlipperScreen을 재시작하세요.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`프린터`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen 재시작`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`재시작 중…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen이 재시작 중입니다 - 곧 화면이 다시 불러와집니다.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen을 재시작할까요?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`변경 사항을 적용하기 위해 터치스크린 서비스를 재시작합니다. 진행 중인 인쇄에는 영향을 주지 않지만, 화면이 몇 초간 검게 표시됩니다.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`재시작`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`취소`}}}}};export{e as default};